import psycopg2

def search_unsafe(conn, term):
    # UNSAFE: the visitor's text becomes part of the SQL statement
    cur = conn.cursor()
    cur.execute("SELECT id, name FROM products WHERE name LIKE '%" + term + "%'")
    return cur.fetchall()

def search_safe(conn, term):
    # SAFE: the statement is fixed; the value travels separately
    cur = conn.cursor()
    cur.execute("SELECT id, name FROM products WHERE name LIKE %s", ("%" + term + "%",))
    return cur.fetchall()

